package com.lianxibu.site.repository.sources;
import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.domain.protocol.SourceContractTelemetry;import com.lianxibu.site.domain.protocol.WireValues;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.JsonNode;import tools.jackson.databind.json.JsonMapper;
/** Permanent source snapshot receipts and monotonic pointers in existing tables. Caller owns the transaction. */
public final class JdbcSourceContractSnapshots {
 private static final String ACTOR="source-telemetry",SCOPE="source-contract-telemetry-v1",OP="source_contract_snapshot";
 private final JdbcTemplate jdbc;
 public record Receipt(String nodeId,long nodeRevision,SourceContractTelemetry.Parsed input,Instant receivedAt,String ackJson){@Override public String toString(){return "SourceSnapshotReceipt[redacted]";}}
 private record Pointer(String id,String hash,long revision){}
 public JdbcSourceContractSnapshots(DataSource source){jdbc=new JdbcTemplate(Objects.requireNonNull(source));}
 public static String actionKey(String node,SourceContractTelemetry.Snapshot snapshot){WireValues.id(node,false);return sha(node+"\n"+snapshot.sourceId()+"\n"+snapshot.epoch()+"\n"+snapshot.sequence());}
 public Receipt committed(String node,SourceContractTelemetry.Parsed input){requireTx();var result=byId(id(actionKey(node,input.snapshot())));if(result==null)return null;if(!node.equals(result.nodeId())||!input.payloadHash().equals(result.input().payloadHash()))throw conflict();return result;}
 public Receipt latest(String node,String source){requireTx();var pointer=pointer(node,source);if(pointer==null)return null;var value=byId(pointer.id());if(value==null||!node.equals(value.nodeId())||!source.equals(value.input().snapshot().sourceId())||!pointer.hash().equals(value.input().payloadHash()))throw conflict();return value;}
 public Receipt save(String node,long nodeRevision,SourceContractTelemetry.Parsed input,Instant now){
  requireTx();if(TransactionSynchronizationManager.isCurrentTransactionReadOnly()||input==null||nodeRevision<1||nodeRevision>CanonicalJson.MAX_SAFE_INTEGER||now==null||now.getEpochSecond()<0||now.getNano()%1000!=0||input.snapshot().observedAt().isAfter(now))throw conflict();WireValues.id(node,false);
  var replay=committed(node,input);if(replay!=null)return replay;var previous=latest(node,input.snapshot().sourceId());var snapshot=input.snapshot();
  if(previous!=null){if(previous.receivedAt().isAfter(now)||previous.input().snapshot().observedAt().isAfter(snapshot.observedAt()))throw conflict();var old=previous.input().snapshot();if(old.epoch().equals(snapshot.epoch())){if(snapshot.sequence()<=old.sequence()||snapshot.totalFailures()<old.totalFailures())throw conflict();for(var event:old.events())if(event.occurredAt().isAfter(snapshot.windowStart())&&!snapshot.events().contains(event))throw conflict();}}
  String action=actionKey(node,snapshot),receipt=id(action);var body=JsonMapper.shared().createObjectNode();body.put("node_revision",nodeRevision);body.set("snapshot",CanonicalJson.parse(input.canonical()));body.put("received_at",time(now));body.put("payload_hash",input.payloadHash());String ack=ack(snapshot,input.payloadHash(),now);byte[] hash=HexFormat.of().parseHex(input.payloadHash());
  jdbc.update("INSERT INTO request_receipts(principal,operation,request_key,request_hash,status_code,response_json,expires_at,id,receipt_kind,actor_id,source_id,scope,key_hash,original_status,current_status,ack_json,result_ref_json,created_at,revision,request_key_raw,business_hash) VALUES(?,?,?,?,200,?,NULL,?,?,?,?,?,?,'applied','applied',?,?,?, ?,?,?)",ps->{Object[] values={node,OP,action,hash,ack,receipt,"collector_control",ACTOR,snapshot.sourceId(),SCOPE,HexFormat.of().parseHex(action),body.toString(),ack,java.sql.Timestamp.from(now),snapshot.sequence(),action,hash};bind(ps,values);});
  var pointer=pointer(node,snapshot.sourceId());var ref=JsonMapper.shared().createObjectNode();ref.put("receipt_id",receipt);ref.put("payload_hash",input.payloadHash());String key=key(node,snapshot.sourceId());
  if(pointer==null)jdbc.update("INSERT INTO runtime_settings(setting_key,value_json,revision,updated_at) VALUES(?,?,1,?)",ps->bind(ps,new Object[]{key,ref.toString(),java.sql.Timestamp.from(now)}));
  else{if(pointer.revision()>=CanonicalJson.MAX_SAFE_INTEGER)throw conflict();if(jdbc.update("UPDATE runtime_settings SET value_json=?,revision=revision+1,updated_at=? WHERE setting_key=? AND revision=?",ps->bind(ps,new Object[]{ref.toString(),java.sql.Timestamp.from(now),key,pointer.revision()}))!=1)throw conflict();}
  return new Receipt(node,nodeRevision,input,now,ack);
 }
 private Pointer pointer(String node,String source){
  var rows=jdbc.query("SELECT CASE WHEN OCTET_LENGTH(value_json) BETWEEN 1 AND 2048 THEN value_json ELSE NULL END,revision FROM runtime_settings WHERE setting_key=?",(r,n)->{if(r.getString(1)==null)throw conflict();var keys=Set.of("receipt_id","payload_hash");var value=WireValues.object(CanonicalJson.parse(r.getString(1)),keys,keys);String id=WireValues.id(value.get("receipt_id"),false);long revision=r.getLong(2);if(revision<1||revision>CanonicalJson.MAX_SAFE_INTEGER)throw conflict();return new Pointer(id,WireValues.sha256(value.get("payload_hash")),revision);},key(node,source));if(rows.size()>1)throw conflict();return rows.isEmpty()?null:rows.getFirst();
 }
 private Receipt byId(String receipt){
  var rows=jdbc.query("SELECT principal,operation,key_hash,request_hash,CASE WHEN OCTET_LENGTH(ack_json) BETWEEN 1 AND 65536 THEN ack_json ELSE NULL END,CASE WHEN OCTET_LENGTH(response_json) BETWEEN 1 AND 4096 THEN response_json ELSE NULL END,business_hash,revision,status_code,expires_at,original_status,current_status,created_at,source_id,request_key_raw,CASE WHEN OCTET_LENGTH(result_ref_json) BETWEEN 1 AND 4096 THEN result_ref_json ELSE NULL END FROM request_receipts WHERE id=? AND actor_id=? AND scope=? AND receipt_kind='collector_control'",(r,n)->{
   if(r.getString(5)==null||r.getString(6)==null||r.getString(16)==null||!OP.equals(r.getString(2))||r.getInt(9)!=200||r.getObject(10)!=null||!"applied".equals(r.getString(11))||!"applied".equals(r.getString(12)))throw conflict();var keys=Set.of("node_revision","snapshot","received_at","payload_hash");var body=WireValues.object(CanonicalJson.parse(r.getString(5)),keys,keys);var input=SourceContractTelemetry.parse(CanonicalJson.bytes(body.get("snapshot")));String node=WireValues.id(r.getString(1),false);long revision=WireValues.nonnegativeInteger(body.get("node_revision"));Instant received=WireValues.utcMicroseconds(body.get("received_at"));String action=actionKey(node,input.snapshot());String expected=ack(input.snapshot(),input.payloadHash(),received);if(revision<1||!receipt.equals(id(action))||!Arrays.equals(r.getBytes(3),HexFormat.of().parseHex(action))||!action.equals(r.getString(15))||!Arrays.equals(r.getBytes(4),HexFormat.of().parseHex(input.payloadHash()))||!Arrays.equals(r.getBytes(7),r.getBytes(4))||!input.payloadHash().equals(WireValues.sha256(body.get("payload_hash")))||r.getLong(8)!=input.snapshot().sequence()||!input.snapshot().sourceId().equals(r.getString(14))||!received.equals(r.getTimestamp(13,utc()).toInstant())||input.snapshot().observedAt().isAfter(received)||!CanonicalJson.parse(expected).equals(CanonicalJson.parse(r.getString(6)))||!CanonicalJson.parse(expected).equals(CanonicalJson.parse(r.getString(16))))throw conflict();return new Receipt(node,revision,input,received,expected);
  },receipt,ACTOR,SCOPE);if(rows.size()>1)throw conflict();return rows.isEmpty()?null:rows.getFirst();
 }
 private static String ack(SourceContractTelemetry.Snapshot s,String hash,Instant now){var value=JsonMapper.shared().createObjectNode();value.put("schema_version","source-contract-telemetry-ack-v1");value.put("source_id",s.sourceId());value.put("config_version",s.configVersion());value.put("epoch",s.epoch());value.put("sequence",s.sequence());value.put("payload_hash",hash);value.put("received_at",time(now));return new String(CanonicalJson.bytes(value),StandardCharsets.UTF_8);}
 private static String key(String node,String source){WireValues.id(node,false);WireValues.id(source,true);return "source-contract:"+sha(node+"\n"+source).substring(0,32);}
 private static String id(String action){return UUID.nameUUIDFromBytes(action.getBytes(StandardCharsets.UTF_8)).toString();}
 private static String time(Instant at){return new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(at);}
 private static String sha(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw conflict();}}
 private static Calendar utc(){return Calendar.getInstance(TimeZone.getTimeZone("UTC"));}
 private static void bind(java.sql.PreparedStatement ps,Object[] values)throws java.sql.SQLException{for(int i=0;i<values.length;i++){if(values[i] instanceof java.sql.Timestamp at)ps.setTimestamp(i+1,at,utc());else ps.setObject(i+1,values[i]);}}
 private static void requireTx(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw conflict();}
 private static IllegalStateException conflict(){return new IllegalStateException("source snapshot proof unavailable");}
}
